var bs = GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A")
for i in range(bs.models.size()):
	var col = i % 5
	var row = int(i / 5)
	bs.models[i]["position"] = {"x": (1.0 + col * 1.3) * 40.0, "y": (57.6 + row * 1.3) * 40.0}
return not RulesEngine.is_unit_engaged("U_BEAST_SNAGGA_BOYZ_A", GameState.state)

var fp = PhaseManager.get_current_phase_instance()
for uid in GameState.state.units:
	if fp.sequencer_11e.eligible_to_fight(uid, GameState.state):
		fp.sequencer_11e.mark_fought(uid, GameState.state)
return fp.get_end_fight_status().step_over

var al = GameState.get_unit("U_ALLARUS_CUSTODIANS_A")
for i in range(al.models.size()):
	al.models[i]["position"] = {"x": (8.0 + i * 1.9) * 40.0, "y": 50.0 * 40.0}
tree.current_scene._recreate_unit_visuals()
var bs = GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A")
var p = bs.models[2]["position"]
var spot = Vector2(float(p["x"]), float(p["y"]))
var shooters = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 1 and RulesEngine.get_eligible_targets(uid, GameState.state).has("U_BEAST_SNAGGA_BOYZ_A"):
		shooters.append(uid)
Engine.set_meta("ih_ghost_spot", spot)
Engine.set_meta("ih_ghost_shooters", shooters)
var oc = MissionManager._check_objective_control({"id": "ih_probe_obj", "position": spot}, GameState.state.units)
if shooters.size() > 0 and oc == 2:
	return "OK"
return "shooters=%d oc=%d" % [shooters.size(), oc]

for m in GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A").models:
	if m.get("position", null) != null:
		return "STILL_ON_BOARD:" + str(m.get("id", ""))
return true

var still = []
for uid in Engine.get_meta("ih_ghost_shooters", []):
	if RulesEngine.get_eligible_targets(uid, GameState.state).has("U_BEAST_SNAGGA_BOYZ_A"):
		still.append(uid)
return still.size()
